W,H=780,700; L,R=78,24
X1=17
PAN=[(24,160,'Tokens per second','tps',27000,31000,(27000,28000,29000,30000,31000)),
     (196,332,'SM clock (MHz)','sm',1700,2000,(1700,1800,1900,2000)),
     (368,504,'Power (W)','pw',44,52,(44,46,48,50,52)),
     (540,640,'Temperature (°C)','tc',78,86,(78,80,82,84,86))]
def sx(h): return L+h/X1*(W-L-R)
def svg(th):
    ink,mut,grid,acc,surf,acc2=th
    o=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    for top,bot,lab,key,y0,y1,ticks in PAN:
        sy=lambda y,top=top,bot=bot,y0=y0,y1=y1: bot-(y-y0)/(y1-y0)*(bot-top)
        for t in ticks:
            o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(t):.1f}" y2="{sy(t):.1f}" stroke="{grid}" stroke-width="1"/>')
            o.append(f'<text x="{L-8}" y="{sy(t)+4:.1f}" fill="{mut}" font-size="12" text-anchor="end">{t:,}</text>')
        for h in range(0,18,2):
            o.append(f'<line x1="{sx(h):.1f}" x2="{sx(h):.1f}" y1="{top}" y2="{bot}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L+6}" y="{top+14}" fill="{ink}" font-size="13" font-weight="bold">{lab}</text>')
        if key=='tps':
            o.append(f'<polyline points="{" ".join(f"{sx(h):.1f},{sy(v):.1f}" for h,v in TPS10)}" fill="none" stroke="{acc}" stroke-width="1.6"/>')
            o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(29408):.1f}" y2="{sy(29408):.1f}" stroke="{acc2}" stroke-width="1.5" stroke-dasharray="6 4"/>')
            o.append(f'<line x1="{W-R-250}" x2="{W-R-226}" y1="{sy(27500):.1f}" y2="{sy(27500):.1f}" stroke="{acc2}" stroke-width="1.5" stroke-dasharray="6 4"/><text x="{W-R-220}" y="{sy(27500)+4:.1f}" fill="{ink}" font-size="12">Part 6 prediction: 29,408</text>')
        if key=='sm':
            o.append(f'<polyline points="{" ".join(f"{sx(b[0]):.1f},{sy(max(b[1],y0)):.1f}" for b in SMI)}" fill="none" stroke="{acc}" stroke-width="1.8"/>')
        if key=='pw':
            o.append(f'<polyline points="{" ".join(f"{sx(b[0]):.1f},{sy(max(b[3],y0)):.1f}" for b in SMI)}" fill="none" stroke="{acc2}" stroke-width="1.6" stroke-dasharray="5 3"/>')
            o.append(f'<polyline points="{" ".join(f"{sx(b[0]):.1f},{sy(max(b[2],y0)):.1f}" for b in SMI)}" fill="none" stroke="{acc}" stroke-width="1.8"/>')
            o.append(f'<line x1="{W-R-250}" x2="{W-R-226}" y1="{top+12}" y2="{top+12}" stroke="{acc}" stroke-width="2"/><text x="{W-R-220}" y="{top+16}" fill="{ink}" font-size="12">draw</text>')
            o.append(f'<line x1="{W-R-170}" x2="{W-R-146}" y1="{top+12}" y2="{top+12}" stroke="{acc2}" stroke-width="2" stroke-dasharray="5 3"/><text x="{W-R-140}" y="{top+16}" fill="{ink}" font-size="12">power limit</text>')
        if key=='tc':
            o.append(f'<polyline points="{" ".join(f"{sx(b[0]):.1f},{sy(min(max(b[4],y0),y1)):.1f}" for b in SMI)}" fill="none" stroke="{acc}" stroke-width="1.8"/>')
    for h in range(0,18,2):
        o.append(f'<text x="{sx(h):.1f}" y="{PAN[-1][1]+20}" fill="{mut}" font-size="13" text-anchor="middle">{h}</text>')
    o.append(f'<text x="{(L+W-R)/2}" y="{H-16}" fill="{ink}" font-size="14" text-anchor="middle">Hours since the run started (18:23 to 11:12 the next day)</text>')
    o.append('</svg>'); return '\n'.join(o)
light=('#0b1a33','#4a5b78','#dde5f2','#0b5fd6','#ffffff','#eb6834')
dark=('#e8eefc','#9fb0cf','#22355a','#38bdf8','#0b162d','#d95926')
open(sys.argv[1]+'.svg','w').write(svg(light)); open(sys.argv[1]+'-dark.svg','w').write(svg(dark))
